/**
 * =============================================================================
 * KS-869 — A KEY'S connectorId MUST SURVIVE THE PROCESS
 * =============================================================================
 * `svc_api_keys.connector_id` has existed since migration 018 and NOTHING in
 * this service wrote it or read it. A key's `connectorId` lived only in the
 * in-process `memApiKeys` map, so it died on every restart — and `loadFromDb()`
 * could not bring it back, because the row mapper did not map the column.
 *
 * What that cost, before this fix:
 *   - `POST /api/keys/validate` returned `connectorId: null` for every Platform
 *     S key after a restart, so the KS-843 grace log — the operator's ONLY
 *     evidence for the cutover flip — could not say WHICH connector was
 *     admitted;
 *   - every connector's gateway `userId` collapsed to `connector:api-key`;
 *   - revoke-on-rotate (KS-577) had no durable way to find a connector's prior
 *     keys, which is how this was found.
 *
 * TWO HALVES, AND BOTH ARE ASSERTED HERE. The mapper can be right while the
 * INSERT drops the column, and the INSERT can be right while the mapper drops
 * it — either alone makes the value un-observable, so a test of one half only
 * would go green on a half-reverted fix.
 * =============================================================================
 */

import { describe, it, expect, beforeAll } from 'vitest';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

/** Statement text only — this file's own prose names the column it pins. */
function codeOf(path: string): string {
  return readFileSync(path, 'utf8')
    .split('\n')
    .filter((l) => !/^\s*(\*|\/\*|\/\/|--)/.test(l))
    .join('\n');
}

const INDEX = join(__dirname, '..', 'index.ts');

let rowToApiKey: (r: Record<string, unknown>) => ReturnType<typeof import("../index").rowToApiKey>;

beforeAll(async () => {
  // index.ts boots a server and the DB unless this is set (its own opt-IN
  // guard, so production behaviour is byte-identical).
  process.env.SECURITY_DISABLE_BOOT = '1';
  ({ rowToApiKey } = await import('../index'));
});

describe('KS-869 — connector_id is persisted and read back', () => {
  it('CONTROL — the mapper is importable and maps a row at all, or every cell below is vacuous', () => {
    const k = rowToApiKey({
      id: 'k1', organization_id: 'o1', tenant_id: 't1', name: 'n', key_hash: 'h',
      key_prefix: 'sk_test', scopes: '[]', rate_limit: 100, rate_limit_window: 60,
      usage_count: 0, is_active: true, created_at: new Date().toISOString(),
    });
    expect(k.id).toBe('k1');
    expect(k.keyPrefix).toBe('sk_test');
  });

  it('🔴 READ half — rowToApiKey maps connector_id onto connectorId', () => {
    const k = rowToApiKey({
      id: 'k2', organization_id: 'o1', tenant_id: 't1', name: 'n', key_hash: 'h',
      key_prefix: 'sk_test', scopes: '[]', rate_limit: 100, rate_limit_window: 60,
      usage_count: 0, is_active: true, created_at: new Date().toISOString(),
      connector_id: 'platform-s:acme-corp',
    });
    expect(k.connectorId).toBe('platform-s:acme-corp');
  });

  it('🔴 READ half — a row with no connector_id yields undefined, not the string "null"', () => {
    // Rows written before this change hold NULL. They must map to undefined so
    // `connectorId || null` downstream stays honest rather than becoming a
    // truthy string.
    const base = {
      id: 'k3', organization_id: 'o1', tenant_id: 't1', name: 'n', key_hash: 'h',
      key_prefix: 'sk_test', scopes: '[]', rate_limit: 100, rate_limit_window: 60,
      usage_count: 0, is_active: true, created_at: new Date().toISOString(),
    };
    expect(rowToApiKey({ ...base }).connectorId).toBeUndefined();
    expect(rowToApiKey({ ...base, connector_id: null }).connectorId).toBeUndefined();
  });

  it('🔴 WRITE half — dbSaveApiKey INSERTs connector_id and passes the value', () => {
    // The mapper cannot see the INSERT, and the INSERT is what actually makes
    // the value durable. Asserted on the STATEMENT, with the comments stripped.
    const code = codeOf(INDEX);
    expect(code, 'connector_id must be in the INSERT column list').toMatch(/INSERT INTO svc_api_keys[\s\S]{0,400}?connector_id/);
    expect(code, 'the value must actually be passed').toContain('k.connectorId ?? null');
    // CONTROL — the pin is on real SQL, not on a comment that mentions it.
    expect(code).toContain('INSERT INTO svc_api_keys');
  });

  it('🔴 WRITE half — the upsert BACKFILLS a NULL but never overwrites a stored value', () => {
    // A plain `EXCLUDED.connector_id` would null a stored value out whenever an
    // in-memory key lacked one; stored-first would never backfill a pre-fix row.
    const code = codeOf(INDEX);
    expect(code).toMatch(/connector_id\s*=\s*COALESCE\(EXCLUDED\.connector_id,\s*svc_api_keys\.connector_id\)/);
  });

  it('CONTROL — no migration is needed: the column already exists', () => {
    const mig = readFileSync(join(__dirname, '..', '..', '..', '..', 'migrations', '018_svc_api_keys_reconcile.sql'), 'utf8');
    expect(mig).toMatch(/ALTER TABLE svc_api_keys ADD COLUMN IF NOT EXISTS connector_id/);
  });
  it('RED KS-880: rowToApiKey answers the default tenant for a row whose tenant_id is missing, null or empty, and passes a stored tenant_id through', () => {
    const base = {
      id: 'k4', organization_id: 'o1', name: 'n', key_hash: 'h',
      key_prefix: 'sk_test', scopes: '[]', rate_limit: 100, rate_limit_window: 60,
      usage_count: 0, is_active: true, created_at: new Date().toISOString(),
    };
    const DEFAULT_TENANT = 'a0000000-0000-4000-8000-000000000001';
    expect([rowToApiKey({ ...base }).tenantId, rowToApiKey({ ...base, tenant_id: null }).tenantId, rowToApiKey({ ...base, tenant_id: '' }).tenantId, rowToApiKey({ ...base, tenant_id: 't9' }).tenantId]).toEqual([DEFAULT_TENANT, DEFAULT_TENANT, DEFAULT_TENANT, 't9']);
  });
});
